import{readFileSync}from'node:fs';import{createHash}from'node:crypto';
import{HandwritingRecordsHost}from'../../host/handwriting-records.mjs';import{MaintenanceIO}from'../../host/maintenance-io.mjs';
const vectors=JSON.parse(readFileSync(new URL('./handwriting-record-management-vectors.json',import.meta.url)));
export const ids=vectors.identities;export const sourceReport=JSON.parse(vectors.cases.find(c=>c.id==='inspect-single').input_json);
export const observation=vectors.cases.find(c=>c.id==='public-prepared-exact').input.observation;
export const identity={connection_id:observation.connection_id,boot_id:observation.boot_id};
export const uuid=n=>`00000000-0000-0000-0000-${n.toString(16).padStart(12,'0')}`;
export const defer=()=>{let resolve;const promise=new Promise(r=>{resolve=r;});return{promise,resolve};};
// Independent fake producer; explicit mechanical fixtures, not Store/native evidence.
function v5(name){const b=createHash('sha1').update(Buffer.from('6ba7b8119dad11d180b400c04fd430c8','hex')).update(name).digest().subarray(0,16);b[6]=(b[6]&15)|80;b[8]=(b[8]&63)|128;const s=b.toString('hex');return`${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`;}
export function fakeHandwritingProducer(){const state={onRaw:null,accepted:new Map(),head:ids.expected_head,removed:false};async function run(body){let r=structuredClone(sourceReport);r.command=body.command;r.record=body.command==='query'?null:ids.record;r.facts[0].revision=state.head;if(body.command==='query'&&state.removed||body.command==='inspect'&&state.removed){r.status=body.command==='query'?'complete-empty':'complete';r.facts=body.command==='query'?[]:[{record:ids.record,revision:state.head,parents:[ids.expected_head],head:true,conflicted:false,state:'tombstone',value:null,sample_availability:'not-applicable'}];r.diagnostics.matched=0;}if(['forget','status'].includes(body.command)){r.operation=body.operation;r.transaction=null;r.facts=[];r.diagnostics.matched=0;if(body.command==='forget'){if(body.expected_heads[0]!==state.head){r.status='conflict';r.failure='heads-conflict';r.diagnostics.mutation_outcome='not-dispatched';}else{const fp=createHash('sha256').update(JSON.stringify(['handwriting-mutation-v1','forget',ids.record,body.expected_heads,null])).digest('hex');const revision=v5('urn:rmb:handwriting-revision:v1:'+body.operation+':'+fp);r.facts=[{record:ids.record,revision,parents:body.expected_heads,head:true,conflicted:false,state:'tombstone',value:null,sample_availability:'not-applicable'}];r.transaction=uuid(8);r.diagnostics.mutation_outcome='observed';state.accepted.set(body.operation,structuredClone(r));state.head=revision;state.removed=true;}}else{const old=state.accepted.get(body.operation);if(old){r={...structuredClone(old),command:'status',transaction:null,historical:true};r.facts[0].head=null;r.facts[0].conflicted=null;}else{r.status='complete-empty';r.diagnostics.mutation_outcome='unknown';}}}if(state.missing&&['inspect','query'].includes(body.command)){r.status='partial';r.diagnostics.missing_media=1;r.diagnostics.matched=1;if(body.command==='query')r.facts=[];else r.facts[0].sample_availability='unavailable';}if(state.loseForget&&body.command==='forget')throw Error('Synthetic lost acknowledgment');if(state.onRaw)r=await state.onRaw(r,body);return r;}return{state,run};}
export function handwritingFixture(options={}){let seq=10,refs=0,clock=0;const calls=[],io=new MaintenanceIO(),producer=fakeHandwritingProducer();const observer={lastObservation:structuredClone(observation),cancels:0,cancel(){this.cancels++;},async run(action,q){if(action!=='handwriting-records')throw Error('Unexpected fixture action');const body=JSON.parse(Buffer.from(q.input_base64,'base64'));calls.push(structuredClone(body));const r=await producer.run(body);return{contract_version:1,status:'observed',observation:structuredClone(this.lastObservation),handwriting_raw:{status:'reported',stdout_base64:Buffer.from(JSON.stringify(r)+'\n').toString('base64')}};}};let hooks=0;const host=new HandwritingRecordsHost({observer,io,beforeIO:()=>{hooks++;},uuid:()=>uuid(seq++),reference:()=>String(++refs).padStart(64,'0'),now:()=>clock,...options});const q=(action,extra={})=>({action,...identity,invocation:uuid(seq++),...extra});return{host,observer,io,calls,producer,q,time:n=>{clock=n;},hooks:()=>hooks};}
export const prepare=async f=>(await f.host.request(f.q('prepare-remove',{profile:ids.profile,correction:ids.correction}))).handwriting_records;
export function addHandwritingFixture(f){const producer=fakeHandwritingProducer(),previous=f.observer.run;f.observer.run=async function(action,q){if(action!=='handwriting-records')return previous.call(this,action,q);const body=JSON.parse(Buffer.from(q.input_base64,'base64'));f.calls.push({action,command:q.command,body});const r=await producer.run(body);return{contract_version:1,status:'observed',observation:structuredClone(this.lastObservation),handwriting_raw:{status:'reported',stdout_base64:Buffer.from(JSON.stringify(r)+'\n').toString('base64')}};};const handwriting=new HandwritingRecordsHost({observer:f.observer,io:f.io}),lanes={...f.lanes,handwriting};for(const[name,h]of Object.entries(lanes))h.beforeIO=()=>{for(const[other,peer]of Object.entries(lanes))if(name!==other)peer.invalidate();};return{...f,handwriting,handwritingProducer:producer,lanes};}
